/** Figma `26779-12391` — Line · Overview */
export function InventisTabsFigma2677912391LineOverview() {
  return <LinePageShell defaultValue="overview" />;
}

/** Figma `26787-33252` — Line · Jobs */
export function InventisTabsFigma2678733252LineJobs() {
  return <LinePageShell defaultValue="jobs" />;
}

"use client";

import * as React from "react";

import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import { cn } from "@/bases/radix/lib/utils";

/** Filter 본문 컬럼과 동일 상한 — 페이지 안에서만 쓰일 때 */
const INVENTIS_MAIN_MAX = "max-w-[1320px]";

export type InventisTabsLineItem = {
  value: string;
  label: string;
  /** `panel` 이 없을 때 플레이스홀더 문구 (Figma Contents A … 등) */
  slotHint?: string;
  /** 탭 패널. 없으면 `slotHint` 기반 muted 플레이스홀더 */
  panel?: React.ReactNode;
};

export type InventisTabsLineProps = {
  /** Radix `Tabs` 기본값 — 미지정 시 `items[0].value` */
  defaultValue?: string;
  items: readonly InventisTabsLineItem[];
  className?: string;
};

function TabsLineSlotPlaceholder({ text }: { text: string }) {
  return (
    <div
      className="border-border bg-muted/40 text-muted-foreground flex min-h-[min(40vh,28rem)] w-full items-center justify-center rounded-lg border border-dashed p-6"
      data-name="Slot"
    >
      <p className="text-center text-sm font-medium">{text}</p>
    </div>
  );
}

/**
 * Inventis DS **Tabs/Line** — 라인 탭 줄 + 패널만 담당합니다.
 *
 * 글로벌 헤더·레일·페이지 제목 행은 **App Header** / **Navigation Sidebar** 등과 조합하세요.
 */
export function InventisTabsLine({
  defaultValue,
  items,
  className,
}: InventisTabsLineProps) {
  const fallback = items[0]?.value ?? "";
  const initial = defaultValue ?? fallback;

  return (
    <div
      className={cn(
        "flex w-full min-w-0 flex-col",
        INVENTIS_MAIN_MAX,
        className,
      )}
    >
      <Tabs
        defaultValue={initial}
        className="flex w-full min-w-0 flex-col gap-4"
      >
        <TabsList
          variant="line"
          className="text-muted-foreground inline-flex h-auto w-full min-w-0 flex-wrap items-center justify-start gap-1 rounded-none bg-transparent p-0"
        >
          {items.map(({ value, label }) => (
            <TabsTrigger
              key={value}
              value={value}
              className="flex-none shadow-none"
            >
              {label}
            </TabsTrigger>
          ))}
        </TabsList>

        {items.map(({ value, label, panel, slotHint }) => (
          <TabsContent
            key={value}
            value={value}
            className="mt-0 min-h-0 outline-none"
          >
            {panel ?? (
              <TabsLineSlotPlaceholder text={slotHint ?? `Panel · ${label}`} />
            )}
          </TabsContent>
        ))}
      </Tabs>
    </div>
  );
}

/** Inventis DS — Tabs (260303_Inventis-DS--Shadcn-ui) */
export const FIGMA_TABS_FILE_KEY = "MvGuEwW5KUn5VcpSEWm2ve";

export const FIGMA_TABS_FILE_BASE = `https://www.figma.com/design/${FIGMA_TABS_FILE_KEY}/260303_Inventis-DS--Shadcn-ui`;

/**
 * 스토리북으로 옮긴 Figma 노드 (재사용 UI·페이지·스펙).
 * 문서 전용 장식만 있는 노드는 제외: `FIGMA_TAB_DOC_EXAMPLE_URL`, `FIGMA_TAB_DOC_TAB_FLOW_URL`.
 */
export const FIGMA_TAB_NODE = {
  /** Variants — Default / Line / Vertical */
  variants: "26779-6787",
  /** Properties — Tabs / Trigger */
  triggerProps: "26779-6920",
  /** Tabs/Line 페이지 — Overview 활성 */
  lineOverview: "26779-12391",
  /** Pattern — Light/Dark 프리뷰 카드 */
  pattern: "26779-6901",
  /** Tabs/Line 페이지 — Jobs 활성 */
  lineJobs: "26787-33252",
} as const;

/** 문서 페이지 장식용 “Example” 라벨 — 컴포넌트 패턴 아님 */
export const FIGMA_TAB_DOC_EXAMPLE_NODE = "26779-6899";

/** 문서 페이지 「Tab Flow」 섹션 띠 — 컴포넌트 패턴 아님 */
export const FIGMA_TAB_DOC_TAB_FLOW_NODE = "26779-12390";

export function figmaTabNodeUrl(nodeId: string): string {
  return `${FIGMA_TABS_FILE_BASE}?node-id=${nodeId}&m=dev`;
}

export const FIGMA_TABS_URL_VARIANTS = figmaTabNodeUrl(FIGMA_TAB_NODE.variants);
export const FIGMA_TABS_URL_TRIGGER_PROPS = figmaTabNodeUrl(
  FIGMA_TAB_NODE.triggerProps,
);
export const FIGMA_TABS_URL_LINE_OVERVIEW = figmaTabNodeUrl(
  FIGMA_TAB_NODE.lineOverview,
);
export const FIGMA_TABS_URL_PATTERN = figmaTabNodeUrl(FIGMA_TAB_NODE.pattern);
export const FIGMA_TABS_URL_LINE_JOBS = figmaTabNodeUrl(
  FIGMA_TAB_NODE.lineJobs,
);
export const FIGMA_TAB_DOC_EXAMPLE_URL = figmaTabNodeUrl(
  FIGMA_TAB_DOC_EXAMPLE_NODE,
);
export const FIGMA_TAB_DOC_TAB_FLOW_URL = figmaTabNodeUrl(
  FIGMA_TAB_DOC_TAB_FLOW_NODE,
);

import type { CSSProperties } from "react";

import {
  FIGMA_TAB_DOC_EXAMPLE_URL,
  FIGMA_TAB_DOC_TAB_FLOW_URL,
  FIGMA_TAB_NODE,
  FIGMA_TABS_FILE_BASE,
  figmaTabNodeUrl,
} from "./tab/figma";

const tableStyle: CSSProperties = {
  width: "100%",
  borderCollapse: "collapse",
  fontSize: "13px",
  margin: "16px 0",
};

const thStyle: CSSProperties = {
  textAlign: "left",
  padding: "8px 12px",
  borderBottom: "1px solid var(--border)",
};

const tdStyle: CSSProperties = {
  padding: "8px 12px",
  borderBottom: "1px solid var(--border)",
  verticalAlign: "top",
};

/** Figma 5노드 ↔ 스토리북 스토리 (Filter Variants 표와 동일 스타일) */
export function TabFigmaFramesTable() {
  const rows: {
    order: number;
    nodeKey: keyof typeof FIGMA_TAB_NODE;
    title: string;
    story: string;
  }[] = [
    {
      order: 1,
      nodeKey: "variants",
      title: "Variants — Default / Line / Vertical",
      story: "Variants",
    },
